insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 16, 'Assim diz o SENHOR dos exércitos: Não deis ouvidos às palavras dos profetas que profetizam para vós; eles vos iludem; falam visão de seus próprios corações, e não da boca do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 17, 'Dizem continuamente aos que me desprezam: O SENHOR diz: Tereis paz; E a qualquer um que segue a teimosia de seu [próprio] coração, dizem: Não virá mal algum sobre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 18, 'Pois quem esteve no conselho do SENHOR, e viu e ouviu sua palavra? Quem prestou atenção a sua palavra, e [a] ouviu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 19, 'Eis que a tempestade da ira do SENHOR já saiu; e a tempestade é violenta, que atingirá violentamente sobre a cabeça dos maus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 20, 'Não se afastará a ira do SENHOR, enquanto não tiver executado e cumprido os pensamentos de seu coração; nos últimos dias entendereis isso claramente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 21, 'Eu não enviei aqueles profetas, porém eles foram correndo; eu não lhes falei, porém eles profetizaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 22, 'Mas se eles tivessem estado em meu conselho, então teriam anunciado minhas palavras a meu povo; e teriam feito com que deixassem seu mau caminho e a maldade de suas ações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 23, 'Por acaso sou eu Deus [apenas] de perto,diz o SENHOR, e não também Deus de longe?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 24, 'Pode alguém se esconder num esconderijo,diz o SENHOR, que eu não o veja? Por acaso não sou eu, diz o SENHOR, que encho os céus e a terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 25, 'Tenho ouvido o que aqueles profetas dizem, profetizando mentiras em meu nome, dizendo: Sonhei, sonhei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 26, 'Até quando [será isto] no coração dos profetas que profetizam mentiras, dos que profetizam o engano de seu coração?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 27, 'Que pretendem, por meio de seus sonhos que cada um conta a seu próximo, fazer com que meu povo se esqueça de meu nome, tal como seus pais se esqueceram de meu nome por causa de Baal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 28, 'O profeta que tiver sonho, conte o sonho; e aquele que tiver minha palavra, conte minha palavra de forma fiel. O que a palha tem a ver com o trigo?,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 29, 'Por acaso não é minha palavra como o fogo?diz o SENHOR, E como um martelo que esmigalha a pedra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 30, 'Portanto eis que eu sou contra os profetas,diz o SENHOR, que furtam minhas palavras cada um de seu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 31, 'Eis que eu sou contra os profetas,diz o SENHOR, que usam suas línguas, e declaram: [Assim] ele disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 32, 'Eis que eu sou contra os que profetizam sonhos mentirosos,diz o SENHOR, e os contam, e fazem meu povo errar com suas mentiras e com suas lisonjas. E eu não os enviei, nem lhes mandei; e proveito nenhum fizeram a este povo, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 33, 'E quando este povo, ou o profeta, ou o sacerdote, te peguntar, dizendo: Qual é a revelação, a carga do SENHOR? Então tu lhes dirás: Que carga? Eu os abandonarei, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 34, 'E quanto ao profeta, o sacerdote, ou alguém do povo, que disser: Carga do SENHOR; eu enviarei castigo sobre tal homem e sobre sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 35, 'Assim direis cada um a seu próximo, e cada um a seu irmão: O que o SENHOR respondeu?, e, O que o SENHOR falou?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 36, 'E nunca mais mencionareis a carga do SENHOR; porque a palavra de cada um lhe servirá por carga; pois pervertestes as palavras do Deus vivente, do SENHOR dos exércitos, nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 37, 'Assim dirás ao profeta: O que o SENHOR te respondeu? e, O que o SENHOR falou?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 38, 'Mas se disserdes: Carga do SENHOR; então por isso o assim diz o SENHOR: Porque dissestes esta palavra, Carga do SENHOR, tendo eu vos mandado, dizendo: Não digais “Carga do SENHOR”,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 39, 'Portanto eis que eu esquecerei totalmente; e lançarei fora de minha presença a vós, e à cidade que dei para vós e para vossos pais;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 23, 40, 'E porei sobre vós humilhação perpétua e vergonha eterna, que nunca será esquecida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 24, 1, 'O SENHOR me mostrou, e eis dois cestos de figos postos diante do templo do SENHOR, depois de Nabucodonosor, rei da Babilônia, haver levado cativo a Jeconias, filho de Jeoaquim, rei de Judá, e aos príncipes de Judá, e aos carpinteiros e ferreiros de Jerusalém, e os ter trazido à Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 24, 2, 'Um cesto [tinha] figos muito bons, como os primeiros figos a ficarem maduros; e a outra cesta tinha figos muito ruins, que não podiam ser comidos de tão ruins.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 24, 3, 'E disse-me o SENHOR: O que tu vês, Jeremias? E eu disse: Figos: os figos bons, muito bons; e os ruins, muito ruins, que de tão ruins não podem ser comidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 24, 4, 'Então veio a mim palavra do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 24, 5, 'Assim diz o SENHOR Deus de Israel: Tal como a estes bons figos, assim [também] conhecerei aos levados de Judá cativos, aos quais mandei embora deste lugar à terra de Caldeus, para o bem [deles] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 24, 6, 'E porei meus olhos sobre eles para o bem, e os farei voltar a esta terra; eu os edificarei, e não os destruirei; eu os plantarei, e não os arrancarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 24, 7, 'E lhes darei coração para que me conheçam, que eu sou o SENHOR; e eles serão meu povo, e eu lhes serei seu Deus; porque se converterão a mim de todo seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 24, 8, 'E tal como os figos ruins, que de tão ruins não podem ser comidos, assim diz o SENHOR, assim [também] farei a Zedequias rei de Judá, e a seus príncipes, e ao resto de Jerusalém que restarem nesta terra, e aos que habitam na terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 24, 9, 'E os farei de motivo de horror para o mal a todos os reinos da terra; de insulto, de ditado, de ridículo, e de maldição a todos os lugares para onde eu os expulsei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 24, 10, 'E enviarei entre eles espada, fome, e pestilência, até que sejam eliminados de sobre a terra que dei a eles e a seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 1, 'Palavra que veio a Jeremias quanto a todo o povo de Judá, no quarto ano de Jeoaquim, filho de Josias, rei de Judá, (o qual é o primeiro ano de Nabucodonosor rei de Babilônia);'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 2, 'A qual o profeta Jeremias falou a todo o povo de Judá, e a todos os moradores de Jerusalém, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 3, 'Desde o ano treze de Josias, filho de Amom, rei de Judá, até este dia, isto é, há vinte e três anos, tem vindo a mim a palavra do SENHOR; e eu tenho vos falado, insistentemente vos falando; porém vós não escutastes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 4, 'E o SENHOR enviou a vós todos seus servos os profetas, insistentemente os enviando; porém vos não escutastes, nem inclinastes vossos ouvidos para escutar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 5, 'Quando diziam: Convertei-vos agora, cada um de seu mau caminho, e da maldade de vossas ações, e habitai na terra que o SENHOR deu a vós e a vossos pais para todo o sempre;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 6, 'E não segui deuses estrangeiros, para os servirdes e encurvardes a eles, nem me provoqueis à ira com a obra de vossas mãos; para que eu não vos faça mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 7, 'Porém vós não me destes ouvidos, diz o SENHOR, para me provocardes à ira com a obra de vossas mãos, para o vosso mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 8, 'Portanto assim diz o SENHOR dos exércitos: Visto quanto não tendes ouvido minhas palavras,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 9, 'Eis que eu enviarei, e tomarei a todas as famílias do norte, diz o SENHOR, e a Nabucodonosor rei de Babilônia, meu servo, e os trarei contra esta terra, e contra seus moradores, e contra todas estas nações ao redor; e os destruirei, e os farei de espanto, assovio, e de desolações perpétuas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 10, 'E eliminarei dentre eles a voz de júbilo e voz de alegria, voz de noivo e voz de noiva, o ruído das pedras de moer, e a luz de lâmpada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 11, 'E toda esta terra se tornará em desolação, [e] em espanto; e estas nações servirão ao rei da Babilônia [por] setenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 12, 'E será que, quando os setenta anos forem completados, punirei ao rei da Babilônia e àquela nação por sua maldade, diz o SENHOR, assim como a terra dos Caldeus; e a tornarei em desolações para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 13, 'E trarei sobre aquela terra todas as minhas palavras que falado contra ela: tudo o que está escrito neste livro, que Jeremias profetizou contra todas as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 14, 'Porque também deles se servirão muitas nações e grandes reis; assim lhes pagarei conforme seus feitos, conforme a obra de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 15, 'Porque assim me disse o SENHOR Deus de Israel: Toma de minha mão este copo de vinho do [meu] furor, e dá de beber dele a todas as nações às quais eu te envio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 16, 'E beberão, tremerão, e enlouquecerão, por causa da espada que eu envio entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 17, 'E eu tomei o copo da mão do SENHOR, e dei de beber a todas as nações às quais o SENHOR tinha me enviado:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 18, 'A Jerusalém, às cidades de Judá; e a seus reis e seus príncipes, para torná-los em desolação, em espanto, em assovio, e em maldição, tal como é hoje;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 19, 'A Faraó rei do Egito, e a seus servos, seus príncipes, e a todo o seu povo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 20, 'E a todas os [povos ali] misturados; e a todos os reis da terra de Uz, e a todos os reis da terra dos filisteus, e a Asquelom, Gaza, e Ecrom; e aos restantes de Asdode;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 21, 'A Edom, Moabe, e aos filhos de Amom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 22, 'E a todos os reis de Tiro, e a todos os reis da Sidom, e aos reis dos litorais que estão além do mar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 23, 'E a Dedã, e Tema, e Buz, e a todos os dos cantos mais distantes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 24, 'E a todos os reis de Arábia, e a todos os reis dos povos misturados que habitam no deserto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 25, 'E a todos os reis de Zinri, e a todos os reis de Elão, e a todos os reis de Média;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 26, 'E a todos os reis do norte, os de perto e os de longe, tanto uns como os outros; e a todos os reinos da terra que estão sobre a face da terra; e o rei de Sesaque beberá depois deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 27, 'Pois tu lhes dirás: Assim diz o SENHOR dos exércitos, Deus de Israel: Bebei, e embriagai-vos, vomitai, caí, e não vos levanteis, por causa da espada que eu envio entre vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 28, 'E será que, se não querem tomar o copo de tua mão para beber, então tu lhes dirás: Assim diz o SENHOR dos exércitos: Certamente bebereis;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 29, 'Pois eis que na cidade que se chama pelo meu nome eu começo a castigar; e vós ficaríeis impunes? Não ficareis impunes, porque eu estou chamando espada contra todos os moradores da terra, diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 30, 'Tu, pois, profetizarás a eles todas estas palavras, e lhes dirás: O SENHOR bramará desde o alto, e levantará sua voz a sua santa morada; bramará intensamente sobre sua morada; dará forte grito, tal como os que pisam as uvas, contra todos os moradores da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 31, 'Chegará o estrondo até o extremo da terra; porque o SENHOR disputa com as nações; entrará em juízo com todos; [e] entregará os perversos à espada, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 32, 'Assim diz o SENHOR dos exércitos: Eis que a calamidade sai de nação em nação, e uma grande tempestade se levantará desde os confins da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 33, 'E os mortos pelo SENHOR naquele dia serão desde um extremo da terra até o outro extremo; não serão lamentados, nem recolhidos, nem sepultados; serão como esterco sobre a face da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 34, 'Uivai, pastores, e clamai; e revolvei-vos [na cinza] , líderes do rebanho; porque já se cumpriram vossos dias para serdes mortos; e sereis dispersos e caireis como um vaso precioso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 35, 'E não haverá meio de fuga para os pastores, nem escape para os líderes do rebanho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 36, 'Haverá voz do grito dos pastores, e uivo dos lideres do rebanho; porque o SENHOR assolou os seus pastos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 37, 'E as pastagens quietas serão devastadas por causa do furor da ira do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 25, 38, 'Ele deixou seu abrigo tal como filhote de leão; pois assolada foi a terra deles, pelo furor do opressor, e pelo furor de sua ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 1, 'No princípio do reinado de Jeoaquim, filho de Josias, rei de Judá, veio esta palavra do SENHOR,dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 2, 'Assim diz o SENHOR: Põe-te no pátio da casa do SENHOR, e fala a todas as cidades de Judá, que vêm para adorar [na] casa do SENHOR, todas as palavras que te mandei que lhes falasses; não diminuas uma só palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 3, 'Pode ser que ouçam, e se convertam cada um de seu mal caminho; então eu me arrependeria do mal que pretendo lhes fazer pela maldade de suas ações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 4, 'Dize-lhes, pois: Assim diz o SENHOR: Se não me ouvirdes para andardes em minha Lei, a qual dei diante de vós,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 5, 'Para dar atenção às palavras de meus servos, os profetas, que eu vos envio, insistentemente os enviando, mas não os ouvistes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 6, 'Então farei desta casa como a Siló, e tornarei esta cidade em maldição a todas as nações da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 7, 'E os sacerdotes, os profetas, e todo o povo, ouviram a Jeremias falar estas palavras na casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 8, 'E sucedeu que, acabando Jeremias de falar tudo o que o SENHOR tinha lhe mandado falar a todo o povo, os sacerdotes e os profetas e todo o povo lhe pegaram, dizendo: Certamente morrerás;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 9, 'Pois profetizaste em nome do SENHOR, dizendo: Esta casa será como Siló, e esta cidade será assolada até não restar morador.E juntou-se todo o povo contra Jeremias na casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 10, 'E os príncipes de Judá, ao ouvirem estas coisas, subiram da casa do rei à casa do SENHOR; e sentaram-se à entrada da porta nova do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 11, 'Então os sacerdotes e os profetas falaram aos príncipes e a todo o povo, dizendo: Pena de morte [deve ter] este homem, pois profetizou contra esta cidade, como ouvistes com vossos [próprios] ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 12, 'E Jeremias falou a todos os príncipes e a todo o povo, dizendo: O SENHOR me enviou para profetizar contra esta casa e contra esta cidade todas as palavras que ouvistes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 13, 'Agora, portanto, melhorai vossos caminhos e vossas ações, e ouvi à voz do SENHOR vosso Deus; então o SENHOR mudará de ideia quanto ao mal que falou contra vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 14, 'Eu, porém, eis que estou em vossas mãos: fazei de mim como parecer melhor e mais correto aos vossos olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 15, 'Mas sabei certamente que, se vós me matardes, então trareis sangue inocente sobre vós, e sobre esta cidade, e sobre seus moradores; porque em verdade o SENHOR me enviou a vós para falar aos vossos ouvidos todas estas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 16, 'Então os príncipes e todo o povo disseram aos sacerdotes e profetas: Este homem não é merecedor de pena de morte, porque em nome do SENHOR nosso Deus ele nos falou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 17, 'E se levantaram alguns dos anciãos da terra, e falaram a todo o ajuntamento do povo, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 18, 'Miqueias, o morastita, profetizou nos dias de Ezequias rei de Judá, e falou a todo o povo de Judá, dizendo: Assim diz o SENHOR dos exércitos: Sião será arada como campo, e Jerusalém se tornará em amontoados [de pedras] , e o monte do templo em lugares altos de mato.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 19, 'Por acaso foi ele morto por Ezequias rei de Judá e todo Judá? Por acaso [Ezequias] não temeu ao SENHOR, e orou na presença do SENHOR, e o SENHOR mudou de ideia quanto ao mal que tinha falado contra eles? E nós, faremos pois tão grande mal contra nossas [próprias] almas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 20, 'Houve também um homem que profetizava em nome do SENHOR: Urias, filho de Semaías de Quiriate-Jearim, o qual profetizou contra esta cidade e contra esta terra, conforme todas as palavras de Jeremias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 21, 'E quando ouviu suas palavras o rei Jeoaquim, e todos seus grandes, e todos seus príncipes, então o rei procurou matá-lo; e Urias, ao ouvir [isso] , teve medo, fugiu, e foi ao Egito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 22, 'Porém o rei Jeoaquim enviou [alguns] homens a Egito: Elnatã filho de Acbor, e [outros] homens com ele, ao Egito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 23, 'Os quais tiraram a Urias do Egito, e o trouxeram ao rei Jeoaquim, que o feriu à espada, e lançou seu cadáver nas sepulturas do povo comum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 26, 24, 'Porém a mão de Aicã, filho de Safã, foi com Jeremias, para que não o entregassem nas mãos do povo para o matarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 1, 'No princípio do reinado de Jeoaquim ,filho de Josias, rei de Judá, veio do SENHOR esta palavra a Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 2, 'Assim me disse o SENHOR: Faz para ti amarras e jugos, e os põe sobre teu pescoço;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 3, 'E envia-os ao rei de Edom, ao rei de Moabe, ao rei dos filhos de Amom, ao rei de Tiro, e ao rei de Sidom, pelas mãos dos mensageiros que vêm a Jerusalém a Zedequias, rei de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 4, 'E manda-lhes que digam a seus senhores: Assim diz o SENHOR dos exércitos, Deus de Israel: Assim direis a vossos senhores:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 5, 'Eu fiz a terra, o homem, e os animais que estão sobre a face da terra, com meu grande poder e com meu braço estendido, e a dou a quem for do meu agrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 6, 'E agora dei todas estas terras na mão de Nabucodonosor, rei de Babilônia, meu servo, e até mesmo os animais do campo eu lhe dei, para que o sirvam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 7, 'E todas as nações servirão a ele, a seu filho, e ao filho de seu filho, até que também venha o tempo de sua própria terra; então servirá a muitas nações e grandes reis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 8, 'E será que a nação e o reino que não servir a Nabucodonosor, rei da Babilônia, e que não puser seu pescoço sob do jugo do rei de Babilônia, então com espada, com fome e com pestilência castigarei tal nação, diz o SENHOR, até que eu os consuma por meio de sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 9, 'E vós não deis ouvidos a vossos profetas, nem a vossos adivinhos, nem a vossos sonhos, nem a vossos videntes, nem a vossos encantadores, que vos falam, dizendo: Não servireis ao rei da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 10, 'Pois eles vos profetizam mentiras, para vos afastardes de vossa terra, e para que eu vos afugente, e pereçais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 11, 'Mas a nação que pôr seu pescoço sob o jugo do rei da Babilônia, e o servir, a essa eu deixarei ficar em seu terra, e a cultivará, e nela habitará diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 12, 'E falei também a Zedequias, rei de Judá, conforme todas estas palavras, dizendo: Ponde vossos pescoços sob o jugo do rei da Babilônia, e servi a ele e a seu povo; então vivereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 13, 'Por que morreríeis, tu e teu povo, pela espada, pela fome, pela pestilência, tal como disse o SENHOR sobre a nação que não servir ao rei da Babilônia?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 14, 'Não escuteis as palavras dos profetas que vos falam, dizendo: Não servireis ao rei da Babilônia; pois eles vos profetizam mentiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 15, 'Pois eu não os enviei, diz o SENHOR, e eles profetizam falsamente em meu nome, para que eu vos afugente, e pereçais, vós e os profetas que vos profetizam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 16, 'Também falei aos sacerdotes e a todo este povo, dizendo: Assim diz o SENHOR: Não escuteis as palavras de vossos profetas, que vos profetizam, dizendo: Eis que os vasos da casa do SENHOR voltarão da Babilônia em breve. Pois eles vos profetizam mentiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 17, 'Não escuteis a eles; servi ao rei de Babilônia, e então vivereis; por que se tornaria esta cidade em deserto?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 18, 'Porém se eles são profetas, e se a palavra do SENHOR é com eles, orem agora ao SENHOR dos exércitos, que os objetos de valor que restaram na casa do SENHOR, na casa do rei de Judá, e em Jerusalém, não vão para a Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 19, 'Porque assim diz o SENHOR dos exércitos quanto às colunas, ao mar, às bases, e ao restante dos objetos de valor que restaram nesta cidade,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 20, 'Que Nabucodonosor, rei da Babilônia, não tomou, quando levou cativo de Jerusalém a Babilônia a Jeconias, filho de Jeoaquim, rei de Judá, e a todos os nobres de Judá e de Jerusalém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 21, 'Assim pois diz o SENHOR dos exércitos, Deus de Israel, quanto aos objetos de valor que restaram [na] casa do SENHOR, e [na] casa do rei de Judá, e [em] Jerusalém:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 27, 22, 'Para a Babilônia serão levados, e ali ficarão até o dia em que eu os punirei, diz o SENHOR; então depois eu os farei subir, e os restituirei a este lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 1, 'E aconteceu no mesmo ano, no princípio do reinado de Zedequias, rei de Judá, no quarto ano, no quinto mês, que Hananias, filho de Azur, profeta que era de Gibeom, falou para mim na casa do SENHOR diante dos sacerdotes e de todo o povo, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 2, 'Assim fala o SENHOR dos exércitos, Deus de Israel, dizendo: Quebrarei o jugo do rei da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 3, 'Dentro do tempo de dois anos, trarei de volta a este lugar todos os objetos de valor da casa do SENHOR, que Nabucodonosor, rei da Babilônia, tomou deste lugar para os levar à Babilônia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 4, 'E eu trarei de volta a este lugar a Jeconias filho de Jeoaquim, rei de Judá, e a todos os levados cativos de Judá que entraram na Babilônia, diz o SENHOR; pois quebrarei o jugo do rei da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 5, 'Então o profeta Jeremias disse ao profeta Hananias, diante dos sacerdotes e diante de todo o povo que estava na casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 6, 'Disse, pois, o profeta Jeremias: Amém! Assim o faça o SENHOR! Que o SENHOR confirme as tuas palavras, com que profetizaste; para que os objetos de valor da casa do SENHOR, e sejam trazidos de volta todos os cativos da Babilônia para este lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 7, 'Porém ouve agora esta palavra, que eu falo aos teus ouvidos e aos ouvidos de todo o povo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 8, 'Os profetas que foram antes de mim e antes de ti, desde os tempos antigos, profetizaram contra muitas terras e grandes reinos, guerra, aflição, e pestilência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 9, 'O profeta que profetizar paz, quando suceder a palavra daquele profeta, será reconhecido tal profeta, que o SENHOR verdadeiramente o enviou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 10, 'Então o profeta Hananias tomou o jugo do pescoço do profeta Jeremias, e o quebrou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 11, 'E falou Hananias diante dos olhos de todo o povo, dizendo: Assim diz o SENHOR: Desta maneira quebrarei o jugo de Nabucodonosor, rei da Babilônia, dentro do tempo de dois anos, de sobre o pescoço de todas as nações. E Jeremias saiu dali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 12, 'Mas depois que o profeta Hananias quebrou o jugo do pescoço do profeta Jeremias, veio a palavra do SENHOR a Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 13, 'Vai, e fala a Hananias, dizendo: Assim diz o SENHOR: Jugos de madeira quebraste, mas farás em seu lugar jugos de ferro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 14, 'Porque assim diz o SENHOR dos exércitos, Deus de Israel: Jugo de ferro pus sobre o pescoço de todas estas nações, para que sirvam a Nabucodonosor rei da Babilônia, e a ele servirão; e até os animais do campo eu lhe dei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 15, 'E disse o profeta Jeremias ao profeta Hananias: Agora ouve, Hananias: o SENHOR não te enviou, porém tu fizeste este povo confiar em mentiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 16, 'Por isso assim diz o SENHOR: Eis que eu te expulso de sobre a face da terra; morrerás neste ano, porque falaste rebelião contra o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 28, 17, 'E morreu o profeta Hananias no mesmo ano, no sétimo mês.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 1, 'Estas são as palavras da carta que o profeta Jeremias enviou de Jerusalém ao restante dos anciãos levados cativos, como também aos sacerdotes e aos profetas, e a todo o povo, que Nabucodonosor havia transportado de Jerusalém para a Babilônia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 2, 'Depois da saída do rei Jeconias, da rainha-mãe, dos príncipes de Judá e Jerusalém, e dos carpinteiros e ferreiros de Jerusalém,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 3, '[Enviada] pela mão de Elasá, filho de Safã, e de Gemarias, filho de Hilquias, os quais Zedequias rei de Judá enviou a Nabucodonosor rei da Babilônia, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 4, 'Assim diz o SENHOR dos exércitos, Deus de Israel, a todos os levados cativos, os quais fiz transportar de Jerusalém à Babilônia:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 5, 'Edificai casas, e [nelas] habitai; plantai hortas, e comei o fruto delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 6, 'Tomai esposas, e gerai filhos e filhas, e tomai esposas para vossos filhos, e dai vossas filhas a homens, para que gerem filhos e filhas; e ali multiplicai-vos, e não vos diminuais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 7, 'E buscai a paz da cidade para onde eu vos levei, e orai por ela ao SENHOR; porque na paz dela vós tereis paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 8, 'Porque assim diz o SENHOR dos exércitos, Deus de Israel: Os vossos profetas, que há entre vós, e vossos adivinhos não vos enganem; nem escutais a vossos sonhos, que vós sonhais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 9, 'Pois eles vos profetizam falsamente em meu nome; eu não os enviei, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 10, 'Porque assim diz o SENHOR: Certamente que, quando se cumprirem setenta anos na Babilônia, eu vos visitarei; e cumprirei sobre vós minha boa palavra, trazendo-vos de volta a este lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 11, 'Porque eu sei os pensamentos que penso quanto a vós, diz o SENHOR, pensamentos de paz, e não de mal, para vos dar um futuro com esperança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 12, 'Então me invocareis, e ireis, e orareis a mim, e eu vos ouvirei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 13, 'E vós me buscareis e achareis, quando me buscardes de todo o vosso coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 14, 'E serei achado por vós, diz o SENHOR, e vos restauarei de vosso infortúnio, e vos ajuntarei de todas as nações, e de todos os lugares para onde eu vos lancei, diz o SENHOR; e vos farei voltar ao lugar de onde vos fiz serdes levados cativos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 15, 'Visto que dizeis: “O SENHOR tem nos levantado profetas na Babilônia”,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 16, 'por isso assim diz o SENHOR acerca do rei que se assenta sobre o trono de Davi, e de todo o povo que mora nesta cidade, os vossos irmãos que não saíram convosco ao cativeiro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 17, 'Assim diz o SENHOR dos exércitos: Eis que enviarei contra eles espada, fome, e pestilência; e farei deles como a figos podres, que de tão ruins não podem ser comidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 18, 'E os perseguirei com espada, com fome e com pestilência; e os farei de horror a todos os reinos da terra, de maldição e de espanto, e de assovio e de humilhação entre todas a nações às quais eu os tiver lançado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 19, 'Porque não deram ouvidos às minhas palavras, diz o SENHOR, que lhes enviei por meus servos os profetas, insistindo em os enviar; próem não escutastes, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 20, 'Vós, pois, ouvi a palavra do SENHOR, todos os do cativeiro que enviei de Jerusalém à Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 21, 'Assim diz o SENHOR dos exércitos, Deus de Israel, quanto a Acabe filho de Colaías, e quanto a Zedequias filho de Maaseias, que vos profetizam falsamente em meu nome: Eis que os entregarei na mão de Nabucodonosor rei da Babilônia, e ele os ferirá diante de vossos olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 22, 'E todos os exilados de Judá que estão na Babilônia, os usarão como objeto de maldição, dizendo: Que o SENHOR faça a ti como a Zedequias e como a Acabe, aos quais o rei de Babilônia assou no fogo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 23, 'porque fizeram loucura em Israel, e cometeram adultério com as mulheres de seus próximos; e falaram falsamente em meu nome palavra que não lhes mandei; e disso eu sei, e sou testemunha, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 24, 'E a Semaías o neelamita falarás, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 25, 'Assim diz o SENHOR dos exércitos, Deus de Israel, dizendo: Enviaste em teu nome cartas a todo o povo que está em Jerusalém, e a Sofonias, filho do sacerdote Maaseias, e a todos os sacerdotes, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 26, 'O SENHOR te pôs por sacerdote em lugar do sacerdote Joiada, para que sejas supervisor na casa do SENHOR sobre todo homem furioso e profetizante, para o lançares na prisão e no tronco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 27, 'Agora, pois, por que não repreendeste a Jeremias de Anatote, que vos profetiza?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 28, 'Porque por isso ele nos mandou dizer na Babilônia: [O cativeiro] será duradouro; edificai casas, e [nelas] morai; plantai hortas, e comei o fruto delas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 29, 'E o sacerdote Sofonias leu esta carta aos ouvidos do profeta Jeremias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 30, 'Então veio a palavra do SENHOR a Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 31, 'Manda dizer a todos os do cativeiro: Assim diz o SENHOR quanto a Semaías, o neelamita: Visto que Semaías vos profetizou, sem que eu tenha o enviado, e vos fez confiar em mentiras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 29, 32, 'Portanto assim diz o SENHOR: Eis que castigarei Semaías o neelamita, e a sua descendência; ele não terá ninguém que habite entre este povo, nem verá o bem que eu farei a meu povo, diz o SENHOR; pois ele falou rebelião contra o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 1, 'Palavra que veio do SENHOR a Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 2, 'Assim diz o SENHOR Deus de Israel, dizendo: Escreve para ti em um livro todas as palavras que tenho te falado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 3, 'Porque eis que vêm dias, diz o SENHOR, em que restaurarei o meu povo, Israel e Judá, de seus infortúnios, diz o SENHOR, e os trarei de volta à terra que dei a seus pais, e a possuirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 4, 'E estas são as palavras que o SENHOR falou quanto a Israel e a Judá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 5, 'Porque assim diz o SENHOR: Ouvimos voz de tremor; há temor, e não paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 6, 'Perguntai pois, e olhai se o homem dá à luz; então por que vejo que todo homem [com] as mãos sobre seus lombos, como [se fosse] mulher de parto? E [por que] todos os rostos ficaram pálidos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 7, 'Ai! Pois aquele dia é tão grande, que não houve outro semelhante; é tempo de angústia para Jacó; porém será livrado dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 8, 'Pois será naquele dia,diz o SENHOR dos exércitos, que eu quebrarei seu jugo de teu pescoço, e romperei tuas amarras; e estrangeiros nunca mais se servirão dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 9, 'Em vez disso servirão ao SENHOR, seu Deus, e a Davi, seu rei, o qual lhes levantarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 10, 'Tu pois, servo meu Jacó, não temas, diz o SENHOR, nem te espantes, ó Israel; porque eis que te salvarei de longe, e a tua descendência da terra do seu cativeiro; e Jacó voltará, descansará e sossegará, e não haverá quem [o] atemorize.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 11, 'Pois estou contigo,diz o SENHOR, para te salvar; e pois exterminarei todas as nações entre a quais te espalhei; porém eu não exterminarei, mas te castigarei com moderação, e não te deixarei impune.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 12, 'Porque assim diz o SENHOR: Teu quebrantamento é incurável, tua ferida é grave.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 13, 'Não há quem julgue tua causa quanto a [tua] enfermidade; não há para ti remédios que curem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 14, 'Todos os teus amantes se esqueceram de ti [e] não te buscam; pois te feri [com] ferida de inimigo, [com] castigo [como] de [alguém] cruel, por causa da grandeza de tua maldade, e da multidão de teus pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 15, 'Por que gritas por causa de teu quebrantamento? Tua dor é incurável; [pois] pela grandeza de tua maldade, [e] pela multidão de teus pecados te fiz estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 16, 'Porém serão devorados todos os que te devoram; e todos os teus adversários, todos eles irão ao cativeiro; e roubados serão os que te roubam, e a todos os que te despojam entregarei para que sejam despojados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 17, 'Mas eu te farei ter saúde, e sararei tuas feridas, diz o SENHOR; pois te chamaram de rejeitada, [dizendo] : Esta é Sião, a quem ninguém busca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 18, 'Assim diz o SENHOR: Eis que restaurarei as tendas de Jacó de seu infortúnio, e me compadecerei de suas moradas; e a cidade será reedificada de suas ruínas, e o templo será posto no lugar de costume.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 19, 'E sairá deles louvor, e voz dos que estão cheios de alegria; e eu os multiplicarei, e não serão diminuídos; eu os glorificarei, e não serão menosprezados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 20, 'E seus filhos serão como no passado; e sua congregação será confirmada diante de mim; e punirei a todos os seus opressores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 21, 'E seu líder será dele, e seu governador saíra do meio dele; e eu o farei chegar perto, e ele se achegará a mim; pois quem jamais confiou em seu próprio coração para se achegar a mim? diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 22, 'E vós sereis meu povo, e eu serei vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 23, 'Eis que a tempestade do SENHOR sai [com] furor, a tempestade impetuosa, que sobre a cabeça dos ímpios cairá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 30, 24, 'A ardente ira do SENHOR não retrocederá enquanto não tiver feito e cumprido os pensamentos de seu coração; no fim dos dias entendereis isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 1, 'Naquele tempo,diz o SENHOR, eu serei o Deus de todas as famílias de Israel, e elas serão o meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 2, 'Assim diz o SENHOR: O povo dos que escaparam da espada encontrou graça no deserto; [este é] Israel, quando eu o fizer descansar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 3, 'O SENHOR apareceu a mim já há muito tempo, dizendo: Com amor eterno eu tenho te amado; por isso com bondade te sustento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 4, 'Novamente te edificarei, e serás edificada, ó virgem de Israel; novamente serás adornada com teus tamborins, e sairás na dança dos que se alegram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 5, 'Novamente plantarás vinhas nos montes de Samaria; os plantadores plantarão, e [delas] desfrutarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 6, 'Pois haverá dia [em que] os vigilantes no monte de Efraim gritarão: Levantai-vos, e subamos a Sião, ao SENHOR nosso Deus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 7, 'Porque assim diz o SENHOR: Cantai por Jacó com alegria, e jubilai por causa da principal de nações; anunciai, louvai, e dizei: Salva, SENHOR, o teu povo, o restante de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 8, 'Eis que eu os trarei da terra do norte, e os juntarei desde os confins da terra, entre os quais haverá cegos e aleijados, mulheres grávidas e as que tiveram parto juntamente; em grande multidão voltarão para cá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 9, 'Virão com choro, e com suplicações os trarei; e os guiarei a ribeiros de águas, por um caminho plano, em que não tropeçarão; porque sou um pai para Israel, e Efraim é meu primogênito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 10, 'Ouvi a palavra do SENHOR, ó nações, e [a] anunciai nos litorais de longe, e dizei: Aquele que espalhou a Israel o juntará e o guardará, tal como um pastor ao seu gado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 11, 'Pois o SENHOR resgatou a Jacó, o livrou da mão do mais forte que ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 12, 'E virão, e jubilarão no lugar alto de Sião, e correrão para o bem do SENHOR: ao trigo, ao suco de uva, ao azeite, e aos cordeiros e bezerros; e a alma deles será como um jardim regado, e nunca mais se enfraquecerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 13, 'Então a virgem se alegrará na dança, como também os jovens e os velhos juntamente; e tornarei seu pranto em alegria, e os consolarei, e os alegrarei em sua tristeza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 14, 'E encherei a alma dos sacerdotes de fartura, e meu povo será saciado com o meu bem, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 15, 'Assim diz o SENHOR: Uma voz foi ouvida em Ramá, lamentação e choro amargo: Raquel chora por seus filhos; não quer ser consolada por causa de seus filhos, pois já não existem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 16, 'Assim diz o SENHOR: Reprime tua voz de choro, e teus olhos de lágrimas; pois há recompensa para teu trabalho, diz o SENHOR, pois voltarão da terra do inimigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 17, 'E há esperança para o teu futuro,diz o SENHOR, pois os [teus] filhos voltarão a suas [próprias] fronteiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 18, 'De fato ouvi Efraim se queixar, [dizendo] : Castigaste-me, e fui castigado como um novilho não domado; converte-me e serei convertido; pois tu és o SENHOR meu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 19, 'Pois depois que me desviei, arrependi-me; depois que entendi, golpeei-me na coxa; envergonhei-me, e me senti humilhado, porque levei a vergonha de minha juventude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 20, 'Por acaso não é Efraim um filho precioso para mim? Não é ele um filho do meu agrado? Pois mesmo tendo eu falado contra ele, eu me lembro dele constantemente. Por isso minhas entranhas se comovem por ele; certamente terei compaixão dele,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 21, 'Levanta para ti sinais, põe para ti marcos altos; presta atenção à vereda, ao caminho [por onde] vieste; volta-te, ó virgem de Israel, volta-te para estas tuas cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 22, 'Até quando andarás sem rumo, ó filha rebelde? Pois o SENHOR criará uma coisa nova sobre a terra: uma fêmea cercará ao varão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 23, 'Assim diz o SENHOR dos exércitos, Deus de Israel: Novamente dirão esta palavra na terra de Judá e em suas cidades, quando eu os restaurar de seu infortúnio: O SENHOR te abençoe, ó morada de justiça, ó monte santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 24, 'E nela habitarão Judá, e em todas as suas cidades juntamente: os lavradores, e os que caminham com o rebanho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 25, 'Porque terei saciado a alma cansada, e enchido toda alma entristecida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 26, '(Nisto me despertei, e olhei; e meu sonho me foi agradável).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 27, 'Diz o SENHOR: Eis que vêm dias, em que semearei a casa de Israel e a casa de Judá com semente de homens e com semente de animais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 28, 'E será que, como tive atenção com eles para arrancar e para derrubar, para transtornar para destruir, e afligir, assim terei atenção com eles para edificar e plantar,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 29, 'Naqueles dias nunca mais dirão: Os pais comeram uvas verdes, mas foram os dentes dos filhos que se estragaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 30, 'Ao contrário, cada um morrerá por sua [própria] maldade; todo homem que comer as uvas verdes estragará seus dentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 31, 'Eis que vêm dias,diz o SENHOR, em que farei um novo pacto com a casa de Jacó e a casa de Judá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 32, 'Não como o pacto que fiz com seus pais, no dia em que os tomei pela mão para os tirar da terra do Egito; pois invalidaram meu pacto, ainda que eu tenha me casado com eles,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 33, 'Mas este é o pacto que farei com a casa de Israel depois daqueles dias,diz o SENHOR: Darei minha lei em seu interior, e a escreverei em seus corações; e eu serei o Deus deles, e eles serão meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 34, 'E não ensinará mais ninguém a seu próximo, nem ninguém a seu irmão, dizendo: Conhece ao SENHOR; pois todos me conhecerão, desde o menor deles até o maior, diz o SENHOR; porque perdoarei a maldade deles, e nunca mais me lembrarei mais de seus pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 35, 'Assim diz o SENHOR, que dá o sol para a luz do dia, [e] as ordenanças da lua e das estrelas para a luz da noite; que divide o mar, e bramam suas ondas; EU-SOU dos exércitos é seu nome:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 36, 'Se estas ordenanças se desviarem diante de mim,diz o SENHOR, também a semente de Israel deixará de ser nação diante de mim para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 37, 'Assim diz o SENHOR: Se os céus acima ser medidos, e [se podem] investigar abaixo os fundamentos da terra, então também eu rejeitarei toda a semente de Israel por tudo quanto fizeram, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 38, 'Diz o SENHOR: Eis que vêm dias em que a cidade [de Jerusalém] será edificada ao SENHOR, desde a torre de Hananeel até a porta da esquina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 39, 'E a linha de medir sairá também diante dela, até sobre à colina de Garebe, e virará ao redor até Goa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 31, 40, 'E todo o vale dos cadáveres e da cinza, e todas os campos até o ribeiro de Cedrom, até a esquina da porta dos cavalos ao oriente, serão consagrados ao SENHOR; nunca mais será arrancada nem derrubada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 1, 'Palavra que veio do SENHOR a Jeremias, no décimo ano de Zedequias rei de Judá, que foi o décimo oitavo ano de Nabucodonosor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 2, '(Quando então o exército do rei da Babilônia tinha cercado a Jerusalém; e o profeta Jeremias estava preso no pátio da guarda, que estava na casa do rei de Judá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 3, 'Pois Zedequias rei de Judá tinha lhe prendido, dizendo: Por que profetizas tu dizendo: Assim diz o SENHOR: “Eis que eu entrego esta cidade na mão do rei da Babilônia, e ele a tomará,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 4, 'E Zedequias rei de Judá não escapará da mão dos caldeus; ao contrário, certamente será entregue na mão do rei da Babilônia, e falará com ele face a face, e seus olhos verão seus olhos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 5, 'E levará Zedequias à Babilônia, e ali ficará até que eu o visite, diz o SENHOR; se lutardes com os Caldeus, não vencereis”?)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 6, 'Disse, pois, Jeremias: A palavra do SENHOR veio a mim, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 7, 'Eis que Hanameel, filho de Salum teu tio, está vindo a ti para dizer: Compra para ti minha propriedade que está em Anatote; pois tu tens o direito de resgate para comprá-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 8, 'E veio a mim Hanameel, filho de meu tio, conforme à palavra do SENHOR, ao pátio da guarda, e me disse: Compra agora minha propriedade que está em Anatote, na terra de Benjamim; pois teu é o direito de herança, e teu é o resgate; compra [-a] para ti. Então entendi que [isto] era a palavra do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 9, 'Assim comprei a propriedade de Hanameel, filho de meu tio, a qual está em Anatote; e pesei para ele o dinheiro: dezessete siclos de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 10, 'E assinei o documento, e o selei, e [o] fiz testemunhar a testemunhas; e pesei o dinheiro em balanças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 11, 'Tomei logo o documento de compra selado, [que continha] os termos e condições, e a [cópia] aberta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 12, 'E dei o documento de compra a Baruque, filho de Nerias, filho de Maasias, diante da vista de Hanameel [filho] de meu tio, e diante da vista das testemunhas que assinaram o documento de compra, [e] diante da vista de todos os judeus que estavam sentados no pátio da guarda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 13, 'E mandei a Baruque diante da vista deles, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 14, 'Assim diz o SENHOR dos exércitos, Deus de Israel: Toma estes documentos, este documento de compra, tanto o que está selado como este documento aberto, e põe-nos em um vaso de barro, para que durem muitos dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 15, 'Pois assim diz o SENHOR dos exércitos, Deus de Israel: Ainda se comprarão casas, campos, e vinhas nesta terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 16, 'E depois que dei o documento de compra a Baruque filho de Nerias, orei ao SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 17, 'Ah Senhor DEUS! Eis que tu fizeste os céus e a terra com teu grande poder, e com teu braço estendido; não há coisa alguma que seja difícil para ti;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 18, 'Tu, que mostras bondade a milhares, e retribuis a maldade dos pais no seio de seus filhos depois deles; o grande, poderoso Deus; EU-SOU dos exércitos é o seu nome;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 19, 'Grande em conselho, e magnífico em feitos; pois teus olhos estão abertos sobre todos os caminhos dos filhos dos homens, para dar a cada um conforme seus caminhos, e conforme o fruto de suas obras;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 20, 'Que puseste sinais e maravilhas na terra do Egito até o dia de hoje, e em Israel, e entre os homens; e fizeste para ti um nome tal como é este dia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 21, 'E tiraste teu povo Israel da terra do Egito com sinais e maravilhas, com mão forte e braço estendido, e com grande espanto;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 22, 'E deste-lhes esta terra, da qual juraste a seus pais lhes dar, terra que mana leite e mel:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 23, 'E entraram, e tomaram posse [dela] ; porém não obedeceram à tua voz, nem andaram em tua lei; nada fizeram do que lhes mandaste fazer; por isso fizeste vir sobre eles todo este mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 24, 'Eis aqui os cercos! Já vieram à cidade para tomá-la; e a cidade está entregue nas mãos dos caldeus que lutam contra ela, por causa da espada, da fome e da pestilência; e o que falaste se cumpriu, e eis que tu estás vendo [isso] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 25, 'Porém tu, ó Senhor DEUS, me disseste: Compra para ti o campo por dinheiro, e faze com que testemunhas testemunhem; mesmo estando a cidade já entregue nas mãos dos caldeus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 26, 'Então veio a palavra do SENHOR a Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 27, 'Eis que eu sou o SENHOR, Deus de toda carne: Existe, por acaso, algo difícil demais para mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 28, 'Portanto assim diz o SENHOR: Eis que eu entrego esta cidade nas mãos dos caldeus, e na mão de Nabucodonosor rei de Babilônia, e ele a tomará;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 29, 'E os caldeus que lutam contra esta cidade entrarão, e incendiarão esta cidade com fogo, e a queimarão, juntamente com as casas sobre cujas terraços ofereceram incenso a Baal e fizeram ofertas de bebidas a deuses estrangeiros, para me provocarem à ira;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 30, 'Pois os filhos de Israel e os filhos de Judá têm feito somente o mal diante dos meus olhos desde sua juventude; porque os filhos de Israel nada têm feito, a não ser somente me provocar à ira com a obra de suas mãos,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 31, 'Pois esta cidade tem me causado minha ira e meu furor desde o dia que a edificaram até hoje, de tal maneira que eu a removerei de minha presença;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 32, 'Por toda a maldade dos filhos de Israel e dos filhos de Judá, que têm feito para me provocarem à ira; eles, seus reis, seus príncipes, seus sacerdotes, seus profetas, os homens de Judá, e os moradores de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 33, 'E viraram para mim as costas, e não o rosto. Ainda que eu tenha lhes ensinado, insistindo em ensinar, contudo se recusaram a ouvir para receberem correção;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 34, 'Ao invés disso, puseram suas abominações na casa que se chama pelo meu nome, para a profanarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 35, 'E edificaram os altos de Baal, que ficam no vale do filho de Hinom, para fazer seus filhos e suas filhas passarem [pelo fogo] a Moloque, o que nunca lhes mandei, nem pensei em meu coração, para que fizessem tal abominação, para fazerem pecar a Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 36, 'E portanto agora assim diz o SENHOR Deus de Israel, quanto a esta cidade, da qual vós dizeis: Já está entregue nas mãos do rei de Babilônia à espada, à fome, e à pestilência:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 37, 'Eis que eu os ajuntarei de todas as terras para onde eu os tiver lançado com minha ira, meu furor e grande indignação; e os farei voltar a este lugar, e os farei habitar em segurança;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 38, 'E eles serão meu povo, e eu lhes serei seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 39, 'E lhes darei um [só] coração e um [só] caminho, para que me temam todos os dias, para o bem deles, e de seus filhos depois deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 40, 'E farei com eles um pacto eterno, que não lhes deixarei de fazer o bem, e porei o temor a mim no coração deles, para que nunca se afastem de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 41, 'E me alegrarei com eles fazendo-lhes bem, e fielmente os plantarei nesta terra , com todo meu coração e com toda a minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 42, 'Pois assim diz o SENHOR: Assim como trouxe sobre este povo todo este grande mal, assim também trarei sobre eles todo o bem que eu lhes prometo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 43, 'E campos serão comprados nesta terra da qual vós dizeis: Está desolada, sem homens e sem animais; está entregue nas mãos dos caldeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 32, 44, 'Campos serão comprados por dinheiro, e se assinarão documentos, e os selarão, e farão testemunhas testificarem, na terra de Benjamim, nos arredores de Jerusalém, e nas cidades de Judá; nas cidades das montanhas, e nas cidades das planícies, e nas cidades do Negueve; porque eu os restaurarei de seu infortúnio, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 1, 'E veio a palavra do SENHOR a Jeremias pela segunda vez, estando ele ainda preso no pátio da guarda, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 2, 'Assim diz o SENHOR que faz [isto] ; o SENHOR, que forma isto para o confirmar; EU-SOU é o seu nome:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 3, 'Clama a mim, e eu te responderei; e te direi coisas grandes e difíceis que tu não conheces.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 4, 'Pois assim diz o SENHOR, Deus de Israel, quanto às casas desta cidade, e às casas dos reis de Judá, que foram derrubadas com as rampas de cerco e com espada:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 5, 'Vieram lutar contra os caldeus, para enchê-las de cadáveres de homens, aos quais feri em minha ira e meu furor; pois escondi meu rosto desta cidade, por causa de toda a sua malícia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 6, 'Eis que eu lhes trarei saúde e cura, e os sararei; e lhes manifestarei abundância de paz e de verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 7, 'E restaurarei Judá de seu infortúnio, e israel de seu infortúnio, e os edificarei como no princípio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 8, 'E os purificarei de toda a sua maldade [com] que pecaram contra mim; e perdoarei todas as suas maldades [com] que pecaram contra mim, e que se rebelaram contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 9, 'E [esta cidade] será para mim como nome de alegria, de louvor e de glória, entre todas as nações da terra, que ouvirem todo o bem que eu lhes faço; e se espantarão e tremerão por causa de todo o bem e de toda a paz que eu lhes darei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 10, 'Assim diz o SENHOR: Neste lugar, do qual dizeis que está desolado, sem homens nem animais, nas cidades de Judá e nas ruas de Jerusalém, que estão desoladas, sem homem, nem morador , nem animal, ainda se ouvirá'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 11, 'Voz de júbilo e voz de alegria, voz de noivo e voz de noiva, e voz dos que dizem: Louvai ao SENHOR dos exércitos, pois o SENHOR é bom; pois sua bondade dura para sempre; [e também] dos que trazem louvor à casa do SENHOR; porque restaurarei esta terra de seu infortúnio para o que era no princípio, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 12, 'Assim diz o SENHOR dos exércitos: Neste lugar desolado, sem homem nem animal, e em todas as suas cidades, haverá novamente morada de pastores, que façam deitar o gado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 13, 'Nas cidades das montanhas, nas cidades das planícies, nas cidades do Negueve, na terra de Benjamim, e ao redor de Jerusalém e nas cidades de Judá, novamente passará o gado pelas mãos dos contadores, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 14, 'Eis que vêm dias, diz o SENHOR, em que eu confirmarei a boa palavra que prometi à casa de Israel e à casa de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 15, 'Naqueles dias e naquele tempo farei brotar a Davi um Renovo de justiça; e ele fará juízo e justiça na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 16, 'Naqueles dias Judá será salvo, e Jerusalém habitará em segurança, e isto é o que a chamarão: O SENHOR [é] a nossa justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 17, 'Pois assim diz o SENHOR: Não faltará a Davi homem que se sente sobre o trono da casa de Israel;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 18, 'Nem aos sacerdotes levitas faltará homem diante de mim que ofereça holocaustos, queime oferta de cereais, e faça sacrifícios todos os dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 19, 'E veio a palavra do SENHOR a Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 20, 'Assim diz o SENHOR: Se puderdes invalidar meu pacto do dia e meu pacto da noite, de tal modo que não haja dia e noite a seu tempo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 21, 'Também se poderá invalidar meu pacto com meu servo Davi, para que não tenha filho que reine sobre seu trono, e com os levitas e sacerdotes, trabalhadores a meu serviço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 22, 'Assim como não se pode contar o exército do céu, nem se pode medir a areia do mar, assim também multiplicarei a descendência de Davi meu servo, e os levitas que me servem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 23, 'E veio a palavra do SENHOR a Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 24, 'Por acaso não tens visto o que este povo fala? Eles dizem: As duas famílias que o SENHOR havia escolhido agora ele as rejeitou. E desprezam a meu povo, como se não o considerassem mais como nação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 25, 'Assim diz o SENHOR: Se meu pacto com o dia e a noite não durasse, se eu não tivesse estabelecido as leis do céu e a terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 33, 26, 'Então também rejeitaria a descendência de Jacó, e de Davi meu servo, para que não tomasse da sua descendência aos que governem sobre a descendência de Abraão, Isaque, e Jacó. Pois eu os restaurarei de seu infortúnio, e deles terei misericórdia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 1, 'Palavra que veio do SENHOR a Jeremias, (quando Nabucodonosor rei da Babilônia, e todo o seu exército, e todos os reinos da terra que estavam sob o domínio de sua mão, e todos os povos, lutavam contra Jerusalém e contra todas as suas cidades), dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 2, 'Assim diz o SENHOR Deus de Israel: Vai, e fala a Zedequias rei de Judá, e dize-lhe: Assim diz o SENHOR: Eis que eu dou esta cidade na mão do rei de Babilônia, e ele a queimará no fogo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 3, 'E tu não escaparás de sua mão; ao contrário, certamente serás preso, e serás entregue na mão dele; e teus olhos verão os olhos do rei da Babilônia, e ele te falará face a face, e entrarás na Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 4, 'Ainda assim, ouve a palavra do SENHOR, ó Zedequias rei de Judá; assim diz o SENHOR quanto ti: Tu não morrerás à espada;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 5, 'Em paz morrerás, e conforme às cerimônias de queimas por teus pais, os primeiros reis, que foram antes de ti, assim queimarão por ti, e prantearão por ti, dizendo: Ai, senhor!; pois eu disse esta palavra, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 6, 'E o profeta Jeremias falou a Zedequias, rei de Judá, todas estas palavras em Jerusalém,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 7, 'Enquanto o exército do rei de Babilônia lutava contra Jerusalém e contra todas as cidades de Judá que haviam restado: contra Laquis, e contra Azeca; pois essas cidades fortificadas haviam restado dentre as cidades de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 8, 'Palavra que veio do SENHOR a Jeremias, depois que o rei Zedequias fez um pacto com todo o povo em Jerusalém, para lhes proclamar liberdade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 9, 'Que cada um libertasse seu servo, e cada um sua serva, hebreu ou hebreia; de maneira que ninguém usasse dos seus irmãos judeus como servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 10, 'E atenderam todos os príncipes, e todo o povo, que entraram no pacto de cada um libertar a seu servo e cada um libertar sua serva, de maneira que ninguém usasse mais deles como servos, atenderam, e os liberaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 11, 'Porém depois se arrependeram, e trouxeram de volta os servos e as servas que haviam libertado, e os sujeitaram para serem servos e servas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 12, 'Então veio a palavra do SENHOR a Jeremias, de parte do SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 13, 'Assim diz o SENHOR, Deus de Israel: Eu fiz um pacto com vossos pais no dia em que os tirei da terra do Egito, da casa de servos, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 14, 'Ao fim de sete anos libertareis cada um a seu irmão hebreu que te for vendido, e tiver servido a ti por seis anos; e o deixarás livre de ti; mas vossos pais não me ouviram, nem inclinaram seu ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 15, 'E recentemente vós havíeis vos convertido, e tínheis feito o correto em meus olhos, proclamando cada um liberdade a seu próximo; e havíeis feito um pacto diante de minha presença, na casa sobre que se chama pelo meu nome:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 16, 'Porém mudastes de ideia e profanastes o meu nome, e trouxestes de volta cada um a seu servo e cada um sua serva, os quais já havíeis libertado à vontade deles; e os sujeitastes para que sejam vossos servos e servas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 17, 'Portanto assim diz o SENHOR: Vós não me ouvistes em proclamar cada um liberdade a seu irmão, e cada um a seu companheiro; eis que eu vos proclamo liberdade, diz o SENHOR, para a espada, para a pestilência, e para a fome; e eu vos tornarei em motivo de espanto a todos os reinos da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 18, 'E entregarei os homens que transgrediram meu pacto, que não cumpriram as palavras do pacto que fizeram diante de mim, dividindo em duas partes o bezerro e passando entre de seus pedaços:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 19, 'Os príncipes de Judá e os príncipes de Jerusalém, os eunucos e os sacerdotes, e todo o povo da terra, que passaram entre os pedaços do bezerro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 20, 'Eu os entregarei na mão de seus inimigos, e na mão dos que buscam [tirar] sua vida; e seus cadáveres serão alimento para as aves do céu, e para os animais da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 21, 'E até a Zedequias, rei de Judá, e a seus príncipes, entregarei na mão de seus inimigos, e na mão dos que buscam [tirar] sua vida, e na mão do exército do rei da Babilônia, que se retiraram de vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 34, 22, 'Eis que eu darei ordem, diz o SENHOR, e os farei voltarem a esta cidade; e lutarão contra ela, e a tomarão, e a queimarão a fogo; e tornarei em desolação as cidades de Judá, de modo que não haja morador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 1, 'Palavra que veio do SENHOR a Jeremias nos dias de Jeoaquim filho de Josias, rei de Judá, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 2, 'Vai à casa dos recabitas, e fala com eles, e leva-os à casa do SENHOR, a uma das câmaras; e dá-lhes de beber vinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 3, 'Tomei então a Jazanias filho de Jeremias, filho de Habazinias, e a seus irmãos, e a todos os seus filhos, e todos da casa dos recabitas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 4, 'E os levei à casa do SENHOR, à câmara dos filhos de Hanã, filho de Jigdalias, homem de Deus, a qual estava junto à câmara dos príncipes, que é acima da câmara de Maaseias filho de Salum, guarda da porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 5, 'E pus diante dos filhos da casa dos recabitas taças e copos cheios de vinho, e disse-lhes: Bebei vinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 6, 'Porém eles disseram: Não beberemos vinho; porque Jonadabe filho de Recabe, nosso pai, nos mandou, dizendo: Nunca bebereis vinho, nem vós nem vossos filhos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 7, 'Nem edificareis casa, nem semeareis semente, nem plantareis vinha, nem a tereis; em vez disso habitareis em tendas todos os vossos dias, para que vivais muitos dias sobre a face da terra onde vós peregrinais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 8, 'E nós temos obedecido à voz de Jonadabe, filho de Recabe, nosso pai; em tudo quanto ele nos mandou, de maneira que não bebemos vinho em todos os nossos dias, nós, nem nossas mulheres, nossos filhos, e nossas filhas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 9, 'Nem edificamos casas para nossa habitação; nem temos vinha, nem campo, nem sementeira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 10, 'E habitamos em tendas, e [assim] temos obedecido e feito conforme a tudo quanto nos mandou Jonadabe nosso pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 11, 'Sucedeu, porém, que quando Nabucodonosor rei de Babilônia subiu a esta terra, dissemos: Vinde, e vamos a Jerusalém, por causa do exército dos caldeus e por causa do exército dos sírios; e [assim] ficamos em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 12, 'Então veio a palavra do SENHOR a Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 13, 'Assim diz o SENHOR dos exércitos, Deus de Israel: Vai, e dize aos homens de Judá, e aos moradores de Jerusalém: Por acaso nunca aceitareis ensino para obedecer a minhas palavras? Diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 14, 'As palavras de Jonadabe, filho de Recabe, que mandou a seus filhos que não bebessem vinho, foram obedecidas; pois não o beberam até hoje, por terem ouvido ao mandamento de seu pai; e eu vos tenho falado, insistindo em falar, mas vós não me ouvistes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 15, 'E enviei a vós a todos os meus servos, os profetas, insistindo em enviá-los, para dizerem: Convertei-vos agora cada um de seu mal caminho, e fazei boas as vossas ações, e não sigais a outros deuses para lhes servi-los, e assim vivereis na terra que dei a vós e a vossos pais; porém não inclinastes vossos ouvidos, nem me obedecestes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 16, 'Dado que os filhos de Jonadabe, filho de Recabe, guardaram o mandamento de seu pai que lhes mandou, mas este povo não me tem obedece,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 17, 'Portanto assim diz o SENHOR Deus dos exércitos, Deus de Israel: Eis que eu trarei sobre Judá e sobre todos os moradores de Jerusalém todo o mal que falei contra eles; pois eu lhes falei, mas não ouviram; eu os chamei, mas não responderam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 18, 'E disse Jeremias aos da casa dos recabitas: Assim diz o SENHOR dos exércitos, Deus de Israel: Por obedecerdes ao mandamento de Jonadabe vosso pai, e guardardes todos os seus mandamentos, e fizerdes conforme a tudo quanto ele vos mandou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 35, 19, 'Portanto, assim diz o SENHOR dos exércitos, Deus de Israel: Nunca faltará homem [da descendência] de Jonadabe, filho de Recabe, que esteja diante de minha presença, todos os dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 1, 'Sucedeu, no quarto ano de Jeoaquim, filho de Josias, rei de Judá, que veio esta palavra do SENHOR a Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 2, 'Toma para ti um rolo de livro, e escreve nele todas as palavras que falei a ti sobre Israel e sobre Judá, e sobre todas as nações, desde o dia que comecei a falar a ti, desde os dias de Josias até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 3, 'Talvez a casa de Judá ouça todo o mal que eu penso lhes fazer; para que cada um se converta de seu mau caminho; então eu perdoarei a maldade e o pecado deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 4, 'Então Jeremias chamou a Baruque, filho de Nerias; e Baruque escreveu da boca de Jeremias, em um rolo de livro, todas as palavras que o SENHOR havia lhe falado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 5, 'E Jeremias mandou a Baruque, dizendo: Eu estou preso, não posso entrar na casa de SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 6, 'Portanto entra tu, e lê do rolo que escreveste de minha boca as palavras do SENHOR aos ouvidos do povo, na casa do SENHOR, no dia do jejum; e também as lerás aos ouvidos de todo Judá, os que vêm de suas cidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 7, 'Talvez a oração deles chegue à presença do SENHOR, e cada um se converta de seu mau caminho; porque grande é a ira e o furor que o SENHOR tem pronunciado contra este povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 8, 'E Baruque filho de Nerias fez conforme a tudo quanto o profeta Jeremias havia lhe mandado, lendo naquele livro as palavras do SENHOR [na] casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 9, 'E aconteceu no quinto ano de Jeoaquim filho de Josias, rei de Judá, no nono mês, que proclamaram jejum diante do SENHOR, a todo o povo em Jerusalém, como também a todo o povo que vinha das cidades de Judá a Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 10, 'Então Baruque leu naquele livro as palavras de Jeremias [na] casa do SENHOR, na câmara de Gemarias, filho de Safã, o escriba, no pático de cima, à entrada da porta nova da casa do SENHOR, aos ouvidos de todo o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 11, 'E Miqueias, filho de Gemarias, filho de Safã, quando ouviu todas as palavras do SENHOR daquele livro,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 12, 'Desceu à casa do rei, à câmara do escriba; e eis que estavam ali sentados todos os príncipes: Elisama, o escriba; Delaías filho de Semeías; Elnatã filho de Acbor; Gemarias filho de Safã; Zedequias filho de Ananias; como também a todos os príncipes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 13, 'E Miqueias lhes anunciou todas as palavras que tinha ouvido enquanto Baruque lia no livro aos ouvidos do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 14, 'Então todos os príncipes enviaram a Jeudi filho de Netanias, filho de Selemias, filho de Cusi, para que dissesse a Baruque: Toma o rolo em que leste aos ouvidos do povo, e vem. Então Baruque filho de Nerias tomou o rolo em sua mão, e veio a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 15, 'E lhe disseram: Senta-te agora, e o lê aos nossos ouvidos. E Baruque leu aos seus ouvidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 16, 'E sucedeu que, quando ouviram todas aquelas palavras, cada um se voltou espantado uns aos outros, e disseram a Baruque: Sem dúvida alguma anunciaremos ao rei todas estas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 17, 'E perguntaram a Baruque, dizendo: Conta-nos agora: como escreveste todas estas palavras? Da boca de [Jeremias] ?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 18, 'E Baruque lhes disse: Ele me ditava de sua boca todas estas palavras, e eu escrevia no livro com tinta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 19, 'Então disseram os príncipes a Baruque: Vai, e esconde-te, tu e Jeremias, e ninguém saiba onde estais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 20, 'E foram ao encontro do rei no pátio, porém o rolo depositaram na câmara de Elisama, o escriba; e contaram aos ouvidos do rei todas aquelas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 21, 'Então o rei enviou a Jeudi para que tomasse o rolo; e o tomou da câmara de Elisama, o escriba, e Jeudi o leu aos ouvidos do rei, e aos ouvidos de todos os príncipes que estavam junto ao rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 22, '(E o rei estava na casa de inverno, no nono mês; e havia diante dele um braseiro aceso);'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 23, 'E sucedeu que, havendo Jeudi lido três ou quatro colunas, rasgou-o com uma lâmina de escrever, e o lançou no fogo que tinha no braseiro, até que todo o rolo se consumiu no fogo que estava no braseiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 24, 'E não temeram, nem rasgaram suas vestes, o rei e todos seus servos que ouviram todas estas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 25, 'E ainda que Elnatã, Delaías e Gemarias tenham rogado ao rei que não queimasse aquele rolo, mesmo assim ele se recusou a os ouvir;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 26, 'Em vez disso, o rei mandou a Jerameel filho do rei, a Seraías filho de Azriel, e a Selemias filho de Abdeel, que prendessem ao escriba Baruque e ao profeta Jeremias; mas o SENHOR havia os escondido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 27, 'Então veio a palavra do SENHOR a Jeremias, depois do rei ter queimado o rolo, e as palavras que Baruque tinha escrito da boca de Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 28, 'Toma de novo outro rolo, e escreve nele todas as primeiras palavras que estavam no primeiro rolo, o qual queimou Jeoaquim, rei de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 29, 'E dirás a Jeoaquim rei de Judá: Assim diz o SENHOR: Tu queimaste este rolo, dizendo: Por que escreveste nele, dizendo: Certamente virá o rei da Babilônia, e destruirá esta terra, e fará com que não fiquem nela homens nem animais?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 30, 'Portanto assim diz o SENHOR quanto a Joaquim rei de Judá: Ele não terá quem se sente sobre o trono de Davi; e seu cadáver será lançado ao calor do dia e à geada da noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 31, 'E punirei a ele, assim como sua semente e os seus servos, por sua perversidade; e trarei sobre eles, sobre os moradores de Jerusalém, e sobre os homens de Judá, todo o mal que tenho lhes dito mas não [quiseram] ouvir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 36, 32, 'Então Jeremias tomou outro rolo, e o deu a Baruque filho de Nerias, o escriba; o qual escreveu nele da boca de Jeremias todas as palavras do livro que Jeoaquim, rei de Judá, tinha queimado a fogo; e ainda foram acrescentadas a elas muitas outras palavras semelhantes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 1, 'E o rei Zedequias, filho de Josias, reinou em lugar de Conias filho de Jeoaquim, ao qual Nabucodonosor, rei da Babilônia, tinha constituído por rei na terra de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 2, 'Porém nem ele, nem seus servos, nem o povo da terra, deram ouvidos às palavras do SENHOR, que falou por meio do profeta Jeremias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 3, 'Porém o rei Zedequias mandou a Jucal filho de Selemias, e a Sofonias filho de Maaseias sacerdote, para que dissessem ao profeta Jeremias: Roga agora por nós ao SENHOR nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 4, 'E Jeremias [tinha liberdade de] entrar e sair entre o povo, pois não o tinham posto na casa do cárcere.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 5, 'E o exército de Faraó havia saído do Egito. E os caldeus que tinham cercado a Jerusalém, ao ouvirem esta notícia, foram embora de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 6, 'Então veio palavra do SENHOR a Jeremias, o profeta, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 7, 'Assim diz o SENHOR Deus de Israel: Assim direis ao rei de Judá, que vos enviou a mim para me perguntar: Eis que o exército de Faraó que saiu para vosso socorro voltará a sua terra, ao Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 8, 'E os caldeus voltarão, e lutarão contra esta cidade; e a tomarão, e a queimarão a fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 9, 'Assim diz o SENHOR: Não enganeis vossas almas, dizendo: Sem dúvida os caldeus irão embora de nós; pois não irão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 10, 'Porque mesmo se ferísseis todo o exército dos caldeus que lutam contra vós, e restassem deles [apenas] homens feridos, ainda assim cada um se levantaria em sua tenda, e queimaria esta cidade a fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 11, 'E aconteceu que, quando o exército dos caldeus havia saído de Jerusalém por causa do exército de Faraó,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 12, 'Jeremias saiu de Jerusalém para ir à terra de Benjamim, para ali receber sua parte no meio do povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 13, 'Porém quando ele chegou à porta de Benjamim, estava ali um capitão dos da guarda, cujo nome era Jerias, filho de Selemias, filho de Hananias; o qual prendeu ao profeta Jeremias, dizendo: Estás te rendendo aos caldeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 14, 'E disse Jeremias diz: Não é verdade; eu não estou me rendendo aos caldeus. Porém ele não lhe deu ouvidos; em vez disso, Jerias prendeu a Jeremias, e o levou aos príncipes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 15, 'E os príncipes se iraram muito contra Jeremias, e o feriram; e o puseram na prisão, na casa do escriba Jônatas, pois a tinham tornado em cárcere.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 16, 'Jeremias entrou na casa da masmorra, e nas celas; e havendo Jeremias estado ali por muitos dias,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 17, 'O rei Zedequias enviou, e mandou trazê-lo; e o rei lhe perguntou em sua casa em segredo, e disse: Há [alguma] palavra do SENHOR? E Jeremias disse: Há. E ele disse: Na mão do rei da Babilônia serás entregue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 18, 'Disse mais Jeremias ao rei Zedequias: Em que pequei contra ti, contra teus servos, e contra este povo, para que me pusésseis no cárcere?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 19, 'E onde estão vossos profetas que vos profetizavam, dizendo: Não virá o rei da Babilônia contra vós, nem contra esta terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 20, 'Agora pois, ouve, por favor, ó rei, meu senhor: chegue, por favor, minha súplica diante de ti, e não me deixes voltar à casa do escriba Jônatas, para que eu não morra ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 37, 21, 'Então o rei Zedequias mandou que pusessem a Jeremias no pátio da guarda, e que lhe dessem uma porção de pão por dia, da rua dos padeiros, até todo o pão da cidade ter se acabado. Assim Jeremias ficou no pátio da guarda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 1, 'Então Sefatias filho de Matã, Gedalias filho de Pasur, Jucal filho de Selemias, e Pasur filho de Melquias, ouviram as palavras que Jeremias falava a todo o povo, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 2, 'Assim diz o SENHOR: Quem ficar nesta cidade morrerá pela espada, pela fome, ou pela pestilência; mas quem sair aos caldeus viverá, pois sua alma lhe será por despojo, e viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 3, 'Assim diz o SENHOR: Certamente esta cidade será entregue nas mãos do exército do rei da Babilônia, que a tomará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 4, 'E os príncipes disseram ao rei: Morra agora este homem; porque assim ele enfraquece as mãos dos homens de guerra que restaram nesta cidade, e as mãos de todo o povo, falando-lhes tais palavras; pois este homem não busca a paz deste povo, mas sim o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 5, 'E disse o rei Zedequias: Eis que ele está em vossas mãos; pois o rei não poderia fazer contra vós coisa alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 6, 'Então eles tomaram a Jeremias, e o lançaram na cisterna de Malquias filho de rei, que estava no pátio da guarda; e meteram a Jeremias com cordas. Porém na cisterna não havia água, mas sim lama; e Jeremias se atolou na lama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 7, 'E Ebede-Meleque, o cuxita, um eunuco que estava na casa do rei, tendo ouvido que haviam posto Jeremias na cisterna, e estando o rei sentado à porta de Benjamim,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 8, 'Logo Ebede-Meleque saiu da casa do rei, e falou ao rei, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 9, 'Ó rei, meu senhor o rei, estes homens fizeram o mal em tudo quanto têm feito com o profeta Jeremias, ao qual lançaram na cisterna; porque ali ele morrerá de fome, pois não há mais pão na cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 10, 'Então o rei mandou a Ebede-Meleque, o cuxita, dizendo: Toma sob tuas ordens trinta homens daqui, e tira ao profeta Jeremias da cisterna, antes que morra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 11, 'E Ebede-Meleque tomou sob suas ordens os homens, e foi à casa do rei, ao lugar debaixo da tesouraria, e tomou dali trapos velhos rasgados, e trapos velhos gastos; e os desceu a Jeremias com cordas na cisterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 12, 'E disse Ebede-Meleque o cuxita a Jeremias: Põe agora esses trapos velhos, rasgados, e gastos abaixo das axilas de teus braços, por debaixo das cordas. E Jeremias assim fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 13, 'E tiraram a Jeremias com as cordas, e o fizeram subir da cisterna; e Jeremias ficou no pátio da guarda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 14, 'Então o rei Zedequias enviou, e mandou trazer a si ao profeta Jeremias à terceira entrada que estava na casa do SENHOR. E disse o rei a Jeremias: Pergunto-te uma coisa; não me encubras nada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 15, 'E Jeremias disse a Zedequias: Se eu te declarar, por acaso não me matarás? E se eu te aconselhar, não me darás ouvido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 16, 'Então o rei Zedequias jurou a Jeremias em segredo, dizendo: Vive o SENHOR que nos fez esta alma, que não te matarei, nem te entregarei nas mãos destes homens que buscam [tirar] tua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 17, 'Então Jeremias disse a Zedequias: Assim diz o SENHOR Deus dos exércitos, Deus de Israel: Se voluntariamente saíres aos príncipes do rei de Babilônia, então tua alma viverá, e esta cidade não será queimada a fogo; e viverás tu e tua casa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 18, 'Mas se não saíres aos príncipes do rei de Babilônia, então esta cidade será entregue nas mãos dos caldeus, e a queimarão a fogo; e tu não escaparás de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 19, 'E disse o rei Zedequias a Jeremias: Eu temo por causa dos judeus que se renderam aos caldeus; que não venham a me entregar em suas mãos, e me maltratem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 20, 'E disse Jeremias: Não te entregarão. Ouve, por favor, a voz do SENHOR que eu te falo, e terás bem, e tua alma viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 21, 'Mas se tu não quiseres sair, esta é a palavra que o SENHOR me mostrou:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 22, 'Eis que todas as mulheres que restaram na casa do rei de Judá serão levadas aos príncipes do rei da Babilônia; e elas mesmas dirão: Os teus amigos te enganaram, e prevaleceram contra ti; teus pés se atolaram na lama, e eles se viraram para trás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 23, 'Assim todas as tuas mulheres e teus filhos serão levados aos caldeus, e tu não escaparás de suas mãos; ao contrário, pela mão do rei da Babilônia serás preso, e esta cidade será queimada a fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 24, 'Então Zedequias disse a Jeremias: Ninguém saiba estas palavras, e então não morrerás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 25, 'E se os príncipes ouvirem que eu falei contigo, vierem a ti, e te disserem: Declara-nos agora o que falaste com o rei; não nos escondas, e não te mataremos; [dize] também o que o rei te falou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 26, 'Então tu lhes dirás: Supliquei ao rei que não me fizesse voltar a casa de Jônatas para eu não morrer ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 27, 'E [depois] vieram todos os príncipes a Jeremias, e lhe perguntaram; e ele lhes respondeu conforme toda as palavras que o rei tinha lhe mandado. Então lhe deixaram, pois a conversa não tinha sido ouvida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 38, 28, 'E Jeremias ficou no pátio da guarda até o dia em que Jerusalém foi tomada; e [ali ainda] estava quando Jerusalém foi tomada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 1, 'No nono ano de Zedequias rei de Judá, no décimo mês, veio Nabucodonosor rei da Babilônia com todo seu exército contra Jerusalém, e a cercaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 2, 'E no décimo primeiro ano de Zedequias, no quarto mês, aos nove do mês, foi rompida a cidade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 3, 'E entraram [nela] todos os príncipes do rei de Babilônia, e se sentaram à porta do meio: Nergal-Sarezer, Sangar-Nebo, Sarsequim, Rabsáris, Nergal-sarezer, Rabmague, e todos os demais príncipes do rei da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 4, 'E sucedeu que, Zedequias, rei de Judá, e todos os homens de guerra, quando os viram, fugiram, e saíram de noite da cidade pelo caminho do jardim do rei, pela porta entre os dois muros; e saíram pelo caminho de Arabá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 5, 'Porém o exército dos caldeus os perseguiu, e alcançaram a Zedequias nas plancíes de Jericó; e o prenderam, e o fizeram subir a Nabucodonosor rei da Babilônia, a Ribla, na terra de Hamate; e ele sentenciou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 6, 'E o rei da Babilônia degolou os filhos de Zedequias em Ribla diante de seus olhos; o rei da Babilônia também degolou a todos os nobres de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 7, 'E cegou os olhos de Zedequias, e o aprisionou com cadeias de bronze, para o levar à Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 8, 'E os caldeus queimaram a casa do rei e as casas do povo a fogo, e derrubaram os muros de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 9, 'E o restante do povo que tinha restado na cidade, e os que haviam a ele se rendido, com todo o resto do povo que tinha restado, Nabuzaradã, capitão da guarda, transportou-os à Babilônia'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 10, 'Porém Nabuzaradã, capitão da guarda, fez restar na terra de Judá os mais pobres do povo, que não tinham nada, e lhes deu vinhas e campos naquele tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 11, 'Mas Nabucodonosor, rei da Babilônia, havia dado ordem a Nabuzaradã, capitão da guarda, quanto a Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 12, 'Toma-o, olha por ele, e não lhe faças mal algum; mas faças com ele como ele te disser.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 13, 'Então enviou Nabuzaradã capitão da guarda, e Nabusasbã, Rabsaris, e Nergal-Sarezer, e Rabmague, e todos os príncipes do rei da Babilônia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 14, 'Enviaram, pois, e tomaram a Jeremias do pátio da guarda, e o entregaram a Gedalias filho de Aicã, filho de Safã, para que o levasse para casa; e ele ficou entre o povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 15, 'E tinha vindo a palavra do SENHOR a Jeremias, enquanto ele estava preso no pátio da guarda, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 16, 'Vai, e fala a Ebede-Meleque o cuxita, dizendo: Assim diz o SENHOR dos exércitos, Deus de Israel: Eis que trarei minhas palavras sobre esta cidade para o mal, e não para o bem; e serão naquele dia perante tua presença.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 17, 'Porém naquele dia eu te livrarei, diz o SENHOR, e não serás entregue nas mãos dos homens a quem tu temes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 39, 18, 'Pois certamente te livrarei, e não cairás à espada, mas sim que terás tua alma como despojo, porque confiaste em mim, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 1, 'Palavra que veio do SENHOR a Jeremias, depois que Nabuzaradã, capitão da guarda, o deixara ir de Ramá; quando o tomou, estando ele acorrentado com cadeias no meio de todos os presos de Jerusalém e de Judá que foram levados cativos à Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 2, 'Pois o capitão da guarda tomou a Jeremias, e lhe disse: O SENHOR teu Deus falou este mal contra este lugar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 3, 'E o SENHOR trouxe e fez o que havia falado; porque pecastes contra o SENHOR, e não obedecestes a sua voz, por isso vos aconteceu isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 4, 'E agora, eis que soltei hoje das cadeias que estavam sobre tuas mãos. Se [parece] bom aos teus olhos vir comigo à Babilônia, vem, e eu olharei por teu bem; mas se te [parece] mau aos teus olhos vir comigo a Babilônia, não o faça; olha, toda a terra está diante de ti; onde [te parecer] melhor e mais correto aos teus olhos ir, para ali vai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 5, 'Mas antes de [Jeremias] ter se virado, [o capitão lhe disse mais] : Volta para Gedalias, filho de Aicã, filho de Safã, ao qual o rei da Babilônia pôs sobre todas as cidades de Judá, e habita com ele em meio do povo; ou vai aonde te [parecer] mais correto aos teus olhos ir. E deu-lhe alimento [para o caminho] , e um presente; e o despediu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 6, 'Assim foi Jeremias a Gedalias filho de Aicã, a Mispá, e habitou com ele em meio do povo que tinha restado na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 7, 'E quando todos os príncipes do exércitos que estavam no campo, eles e seus homens, ouviram que o rei da Babilônia tinha posto a Gedalias filho de Aicã sobre a terra, e que tinha lhe encarregado dos homens, mulheres, e crianças, e os pobres da terra, os quais não foram levados em cativeiro à Babilônia,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 8, 'Vieram, pois, a Gedalias em Mispá. [Eram eles] : Ismael, filho de Netanias, Joanã e Jônatas, filhos de Careá, Seraías, filho de Tanumete, os filhos de Efai, o netofatita, e Jezanias, filho do maacatita; eles e seu homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 9, 'E Gedalias filho de Aicã, filho de Safã, jurou a eles e a seus homens, dizendo: Não temais servir aos caldeus; habitai na terra, e servi ao rei da Babilônia, e tereis bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 10, 'E eis que eu habito em Mispá, para estar diante dos caldeus que vierem a nós; e vós, colhei o vinho, os frutos do verão, e o azeite, e [os] ponde em vossos vasos, e habitai em vossas cidades que tomastes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 11, 'E da mesma maneira todos os judeus que estavam em Moabe, e entre os filhos de Amom, e em Edom, e os que [estavam] em todas as terras, ouviram dizer que o rei da Babilônia tinha deixado alguns em Judá, e que tinha posto sobre eles a Gedalias filho de Aicã, filho de Safã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 12, 'Todos estes judeus voltaram então de todas as partes para onde haviam sido lançados, e vieram à terra de Judá, a Gedalias em Mispá; e colheram vinho e muitos frutos de verão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 13, 'E Joanã filho de Careá, e todos os comandantes dos exércitos que estavam em campo, vieram a Gedalias em Mispá,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 14, 'E lhe disseram: Com certeza tu sabes que Baalis, rei dos filhos de Amom, enviou a Ismael filho de Netanias, para te matar, não é verdade? Porém Gedalias filho de Aicã não creu neles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 15, 'Então Joanã filho de Careá falou a Gedalias em segredo, em Mispá, dizendo: Eu irei agora, e ferirei a Ismael filho de Netanias, e ninguém saberá; por que haveria ele de te matar, e todos os judeus que se ajuntaram a ti se dispersarem, e perecerem o restante de Judá?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 40, 16, 'Mas Gedalias filho de Aicã disse a Joanã filho de Careá: Não faças isto, pois o que tu dizes de Ismael é falso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 1, 'Sucedeu, porém, no sétimo mês, que Ismael filho de Netanias, filho de Elisama, da semente real, veio com alguns capitães do rei, dez homens com ele, até Gedalias filho de Aicã em Mispá; e comeram pão juntos ali em Mispá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 2, 'Então levantou-se Ismael filho de Netanias, e os dez homens que com ele estavam, e feriram à espada a Gedalias filho de Aicã, filho de Safã, matando assim a aquele a quem o rei da Babilônia tinha posto sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 3, 'Assim também Ismael feriu a todos os judeus que estavam com ele, com Gedalias em Mispá, e aos soldados caldeus que ali se acharam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 4, 'Aconteceu, pois, no dia seguinte, depois que havia matado a Gedalias, quando ninguém sabia ainda,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 5, 'Que vieram homens de Siquém, de Siló, e de Samaria, oitenta homens, tendo a barba raspada, e as roupas rasgadas, e tendo ferido seus próprios corpos; e [traziam] em suas mãos oferta de alimentos e incenso para levar à casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 6, 'E Ismael filho de Netanias saiu ao encontro deles desde Mispá, chorando; e sucedeu que, quando os encontrou, disse-lhes: Vinde a Gedalias, filho de Aicã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 7, 'E sucedeu que, quando eles chegaram ao meio da cidade, Ismael filho de Netanias os degolou, e [os lançou] no meio de um poço, ele e os homens que com ele estavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 8, 'Mas entre aqueles se acharam dez homens que disseram a Ismael: Não nos mates; porque temos tesouros escondidos no campo, de trigos, e cevada, azeite, e mel. E ele os deixou, e não os matou entre seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 9, 'E o poço em que Ismael lançou todos os cadáveres dos homens que feriu por causa de Gedalias, era o mesmo que o rei Asa havia feito por causa de Baasa, rei de Israel. A este Ismael, filho de Netanias, encheu de mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 10, 'Depois Ismael levou cativo a todo o resto do povo que estava em Mispá; às filhas do rei, e a todo o povo que em Mispá tinha restado, o qual tinha Nabuzaradã capitão da guarda havia encarregado a Gedalias filho de Aicã. Então Ismael os levou cativos, e foi embora, para passar aos filhos de Amom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 11, 'E quando Joanã filho de Careá, e todos os comandantes dos exércitos que estavam com ele, ouviram todo o mal que Ismael filho de Netanias tinha feito,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 12, 'Tomaram a todos os homens, e foram lutar contra Ismael filho de Netanias; e o acharam junto às muitas águas que ficam em Gibeão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 13, 'E aconteceu que, quando todo o povo que estava com Ismael viu a Joanã filho de Careá, e a todos os comandantes dos exércitos que estavam com ele, alegraram-se.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 14, 'E todo o povo que Ismael tinha levado cativo de Mispá, viraram-se, e se voltaram, e foram a Joanã filho de Careá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 15, 'Porém Ismael filho de Netanias escapou com oito homens diante de Joanã, e se foi aos filhos de Amom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 16, 'Então Joanã filho de Careá, e todos os comandantes dos exércitos que com ele estavam, tomaram todo o resto do povo que tinham trazido de volta de Ismael filho de Netanias, de Mispá, depois dele ter ferido a Gedalias filho de Aicã: homens valentes de guerra, mulheres, e crianças; e os eunucos, que tinha trazido de volta de Gibeão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 17, 'E foram, e habitaram em Gerute-Quimã, que é perto de Belém, a fim de saírem [dali] para entrarem no Egito,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 41, 18, 'Por causa dos caldeus; pois eles temiam por Ismael filho de Netanias ter ferido a Gedalias filho de Aicã, ao qual o rei de Babilônia tinha posto sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 1, 'Então chegaram todos os comandantes dos exércitos, e Joanã filho de Careá, e Jezanias filho de Hosaías, e todo o povo desde o menor até o maior,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 2, 'E disseram ao profeta Jeremias: Chegue, por favor, nossa suplicação diante de ti, e roga por nós ao SENHOR teu Deus, por todo este restante; pois de muitos restamos [apenas] uns poucos, como teus olhos nos veem,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 3, 'Para que o SENHOR teu Deus nos ensine caminho por onde devemos andar, e o que temos de fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 4, 'E Jeremias profeta lhes disse: Eu ouvi. Eis que orarei ao SENHOR vosso Deus, conforme vossas palavras; e será que toda palavra que o SENHOR vos responder, eu vos anunciarei; não vos esconderei palavra alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 5, 'Então eles disseram a Jeremias: O SENHOR seja entre nós testemunha da verdade e da fidelidade, se não fizermos conforme a toda palavra com que o SENHOR teu Deus te enviar a nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 6, 'Seja bem ou seja mal, obedeceremos à voz do SENHOR nosso Deus, ao qual te enviamos; para que, obedecendo à voz do SENHOR nosso Deus, tenhamos bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 7, 'E aconteceu que ao fim de dez dias veio a palavra do SENHOR a Jeremias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 8, 'Então ele chamou a Joanã filho de Careá, e a todos os comandantes dos exércitos que com ele estavam, e a todo o povo desde o menor até o maior;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 9, 'E disse-lhes: Assim diz o SENHOR Deus de Israel, ao qual me enviastes para que eu apresentasse vossa suplicação diante de sua presença:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 10, 'Se ficardes nesta terra, então eu vos edificarei, e não vos destruirei; eu vos plantarei, e não vos arrancarei; pois ressentido estou do mal que tenho vos feito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 11, 'Não temais ao rei da Babilônia, do qual tendes medo; não o temais, diz o SENHOR, pois eu estou convosco para vos salvar e vos livrar de sua mão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 12, 'E vos concederei misericórdia, de modo que ele tenha misericórdia de vós, e vos faça voltar a vossa terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 13, 'Mas se disserdes: Não ficaremos nesta terra, desobedecendo à voz do SENHOR vosso Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 14, 'E dizendo: Não, em vez disso iremos à terra do Egito, na qual não veremos guerra, nem ouviremos som de trombeta, nem teremos fome de pão, e ali ficaremos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 15, 'Então assim ouvi a palavra do SENHOR, ó restantes de Judá; assim diz o SENHOR dos exércitos, Deus de Israel: Se dirigirdes vossos rostos para entrar no Egito, e irdes para peregrinar ali,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 16, 'Será que a espada que vós temeis, ali ela vos tomará na terra do Egito, e a fome que vos deixa preocupados, ali no Egito ela vos pegará; e ali morrereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 17, 'Assim será com todos os homens que dirigirem seus rostos para irem ao Egito, para ali peregrinar: morrerão pela espada, pela fome, e pela pestilência; não haverá um deles sequer que reste vivo, nem que escape do mal que eu trarei sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 18, 'Porque assim diz o SENHOR dos exércitos, Deus de Israel: Tal como se derramou minha ira e minha indignação sobre os moradores de Jerusalém, assim também se derramará minha indignação sobre vós, quando entrardes no Egito; e servireis de maldição e de espanto; de amaldiçoamento e de humilhação; e não vereis mais a este lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 19, 'O SENHOR já falou quanto vós, ó restantes de Judá: Não entreis no Egito; Tende certeza de que eu vos advirto hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 20, 'Porque levais vossas próprias almas ao erro; pois vós me enviastes ao SENHOR vosso Deus, dizendo: Ora por nós ao SENHOR nosso Deus; e conforme a tudo quanto o SENHOR nosso Deus disser, assim nos faz saber, e o faremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 21, 'E eu já vos fiz saber hoje, porém não destes ouvidos à voz do SENHOR vosso Deus, nem a tudo pelo que ele me enviou a vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 42, 22, 'Agora, portanto, tende certeza de que pela espada, pela fome, e pela pestilência, morrereis no lugar onde desejastes entrar para ali peregrinardes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 43, 1, 'E sucedeu que, quando Jeremias acabou de falar a todo o povo todas as palavras do SENHOR Deus deles, pelas quais o SENHOR Deus deles tinha o enviado a eles,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 43, 2, 'Então Azarias filho de Hosaías, e Joanã filho de Careá, e todos os homens arrogantes disseram a Jeremias: Tu falas mentira! O SENHOR nosso Deus não te enviou para dizer: Não entreis em Egito para ali peregrinar.')
